    # output marks the positions present in exactly one figure.
    def components(color):
        seen = set()
        result = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                comp = []
                while stack:
                    x, y = stack.pop()
                    comp.append((x, y))
                    for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx,ny) not in seen:
                            seen.add((nx,ny))
                            stack.append((nx,ny))
                result.append(comp)
        return result

    # Locate sizable nonzero objects by their color-1 frame pixels.
    ones = components(1)
    boxes = []
    for comp in ones:
        rs = [r for r, c in comp]
        cs = [c for r, c in comp]
        if len(comp) >= 3:
            boxes.append((min(rs), max(rs), min(cs), max(cs)))
    boxes.sort(key=lambda b: (b[0], b[2]))

    # Pick the separated, upper pair of complex motifs.
    if len(boxes) < 2:
        return [[0]]
    upper = [b for b in boxes if b[0] < h // 2]
    if len(upper) >= 2:
        a, b = upper[0], upper[-1]
    else:
        a, b = boxes[0], boxes[-1]

    ah, aw = a[1]-a[0]+1, a[3]-a[2]+1
    bh, bw = b[1]-b[0]+1, b[3]-b[2]+1
    oh, ow = max(ah, bh), max(aw, bw)
