def transform(grid):
    # The output is a compact binary signature of the isolated framed panel.
    # Locate a panel with a 1-colored border and a 3-colored interior.
    h, w = len(grid), len(grid[0])
    best = None

    for r0 in range(h):
        for c0 in range(w):
            if grid[r0][c0] != 1:
                continue
            for r1 in range(r0 + 2, h):
                for c1 in range(c0 + 2, w):
                    if (grid[r0][c1] == 1 and grid[r1][c0] == 1
                            and grid[r1][c1] == 1):
                        interior = [(r, c) for r in range(r0+1, r1)
                                    for c in range(c0+1, c1)
                                    if grid[r][c] == 3]
                        if interior:
                            area = (r1-r0+1) * (c1-c0+1)
                            if best is None or area > best[0]:
                                best = (area, r0, c0, r1, c1)

    if best is None:
        return [[0]]
    _, r0, c0, r1, c1 = best
    out = []
    for r in range(r0, r1+1):
        row = []
        for c in range(c0, c1+1):
            row.append(8 if grid[r][c] == 3 else 0)
        out.append(row)
    return out
